   if(status=='approved')update['approved_at']=stamp;if(status=='paid')update['paid_at']=stamp;
   await _db.from('erp_construction_payment_certificates').update(update).eq('company_id',co).eq('id',id);
  }
  if(table=='erp_asset_disposals'&&status=='approved'){
   await _db.from('erp_fixed_assets').update({'status':'disposed','updated_at':DateTime.now().toIso8601String()}).eq('company_id',co).eq('id',data['asset_id']);
  }
  if(table=='erp_asset_movements'&&status=='approved'){
   final updates=<String,dynamic>{'updated_at':DateTime.now().toIso8601String()};
   if((d['to_location']??'').toString().isNotEmpty)updates['location']=d['to_location'];
   if((d['custodian']??'').toString().isNotEmpty)updates['custodian']=d['custodian'];
   if((d['movement_type']??'').toString().contains('صيانة'))updates['status']='under_maintenance';
   await _db.from('erp_fixed_assets').update(updates).eq('company_id',co).eq('id',data['asset_id']);
  }
  if(table=='erp_production_orders'){
   final orderRows=await _db.from('erp_production_orders').select('warehouse_id,product_id,lot_number,planned_quantity,estimated_cost,actual_cost').eq('company_id',co).eq('id',id).limit(1);
   if(orderRows.isEmpty)throw Exception('تعذر قراءة أمر التصنيع بعد الحفظ.');
   final order=orderRows.first;final warehouseId=order['warehouse_id']?.toString();
   final materialText=(d['materials']??'').toString().trim();
   if(materialText.isNotEmpty){
    final already=await _db.from('erp_production_material_movements').select('id').eq('company_id',co).eq('production_order_id',id).limit(1);
    if(already.isEmpty){
     if(warehouseId==null)throw Exception('حدد المخزن قبل صرف خامات أمر التصنيع.');
     final lines=materialText.split(RegExp(r'[\n;]+')).where((x)=>x.trim().isNotEmpty).toList();
     final required=<String,Map<String,dynamic>>{};
     for(final line in lines){
      final parts=line.split('|').map((x)=>x.trim()).toList();if(parts.length<2)continue;
      final q=_n(parts[1]);if(parts[0].isEmpty||q<=0)continue;
      final byCode=await _db.from('erp_items').select('id,item_name,base_unit,purchase_price').eq('company_id',co).eq('item_code',parts[0]).limit(1);
      final itemRows=byCode.isNotEmpty?byCode:await _db.from('erp_items').select('id,item_name,base_unit,purchase_price').eq('company_id',co).eq('item_name',parts[0]).limit(1);
      if(itemRows.isEmpty)throw Exception('الصنف '+parts[0]+' غير موجود في دليل الأصناف.');
      final item=itemRows.first, itemId=item['id'].toString();
      final unit=parts.length>2&&parts[2].isNotEmpty?parts[2]:(item['base_unit']??'وحدة').toString();
      final unitCost=parts.length>3&&parts[3].isNotEmpty?_n(parts[3]):_n(item['purchase_price']);
      final current=required[itemId];
      if(current==null){required[itemId]={'item':item,'quantity':q,'unit':unit,'unit_cost':unitCost};}
      else{current['quantity']=_n(current['quantity'])+q;current['unit_cost']=unitCost;}
     }
     for(final entry in required.entries){
      final spec=entry.value,item=spec['item'];final alreadyRows=await _db.from('erp_production_material_movements').select('quantity').eq('company_id',co).eq('production_order_id',id).eq('item_id',entry.key);
      final already=(alreadyRows as List).fold<double>(0,(sum,row)=>sum+_n(row['quantity']));
      final wanted=_n(spec['quantity']);if(already>wanted)throw Exception('الكمية المسجلة للصنف '+item['item_name']+' أكبر من الكمية المطلوبة في تفاصيل الأمر.');
      final delta=wanted-already;if(delta<=0)continue;
      await _db.rpc('erp_record_production_stock_movement',params:{'p_company_id':co,'p_production_order_id':id,'p_warehouse_id':warehouseId,'p_item_id':entry.key,'p_item_name':item['item_name'],'p_quantity':delta,'p_unit':spec['unit'],'p_unit_cost':spec['unit_cost'],'p_movement_date':date,'p_lot_number':order['lot_number'],'p_movement_kind':'issue'});
     }
    }
   }
   final produced=_n(d['produced_qty']);
   if(produced>0){
    final productId=order['product_id']?.toString();if(productId==null||warehouseId==null)throw Exception('اختر صنف المنتج النهائي والمخزن قبل استلام الإنتاج.');
    final receipts=await _db.from('erp_inventory_movements').select('quantity_in').eq('company_id',co).eq('reference_type','production_order').eq('reference_id',id).eq('movement_type','production_receipt');
    final received=(receipts as List).fold<double>(0,(sum,row)=>sum+_n(row['quantity_in']));
    if(produced<received)throw Exception('لا يمكن تقليل كمية الإنتاج عن الكمية التي تم استلامها بالمخزون بالفعل.');
    final delta=produced-received;
    if(delta>0){
     final itemRows=await _db.from('erp_items').select('item_name,base_unit').eq('company_id',co).eq('id',productId).limit(1);
     if(itemRows.isEmpty)throw Exception('تعذر العثور على المنتج النهائي.');
     final unitCost=_n(order['actual_cost'])>0?_n(order['actual_cost'])/produced:_n(order['estimated_cost'])/(_n(order['planned_quantity'],1));
     await _db.rpc('erp_record_production_stock_movement',params:{'p_company_id':co,'p_production_order_id':id,'p_warehouse_id':warehouseId,'p_item_id':productId,'p_item_name':itemRows.first['item_name'],'p_quantity':delta,'p_unit':itemRows.first['base_unit'],'p_unit_cost':unitCost,'p_movement_date':date,'p_lot_number':order['lot_number'],'p_movement_kind':'receipt'});
    }
   }
  }
  if(table=='erp_manufacturing_boms'&&(d['components']??'').toString().trim().isNotEmpty){
   await _db.from('erp_manufacturing_bom_lines').delete().eq('company_id',co).eq('bom_id',id);
   final lines=(d['components']??'').toString().split(RegExp(r'[\n;]+')).where((x)=>x.trim().isNotEmpty).toList();
   var lineNo=0;final parsed=<Map<String,dynamic>>[];
   for(final line in lines){final parts=line.split('|').map((x)=>x.trim()).toList();if(parts.length<2)continue;final q=_n(parts[1]);if(parts[0].isEmpty||q<=0)continue;lineNo++;final byCode=await _db.from('erp_items').select('id,item_name,base_unit').eq('company_id',co).eq('item_code',parts[0]).limit(1);final items=byCode.isNotEmpty?byCode:await _db.from('erp_items').select('id,item_name,base_unit').eq('company_id',co).eq('item_name',parts[0]).limit(1);parsed.add({'company_id':co,'bom_id':id,'line_no':lineNo,'item_id':items.isEmpty?null:items.first['id'],'item_name':items.isEmpty?parts[0]:items.first['item_name'],'quantity':q,'unit':parts.length>2&&parts[2].isNotEmpty?parts[2]:(items.isEmpty?'وحدة':items.first['base_unit'])});}
   if(parsed.isNotEmpty)await _db.from('erp_manufacturing_bom_lines').insert(parsed);
  }
  if(table=='erp_service_tickets'&&oldRow!=null&&oldRow['status']!=status){
   await _db.from('erp_service_ticket_events').insert({'company_id':co,'ticket_id':id,'event_type':'status_change','from_status':_ticketStatus(oldRow['status']),'to_status':_ticketStatus(status),'note':'تغيير حالة التذكرة من شاشة سلسلة'});
  }
  return {...d,'_operational_table':table,'_operational_id':id};
 }

 String get _reportTable {
  final p=widget.page;
  if(_moduleKey=='fixed_assets'){if(p.contains('إهلاك'))return 'erp_asset_depreciation_runs';if(p.contains('استبعاد')||p.contains('بيع أصل'))return 'erp_asset_disposals';if(p.contains('حركة')||p.contains('نقل'))return 'erp_asset_movements';return 'erp_fixed_assets';}
  if(_moduleKey=='manufacturing'){if(p.contains('هالك')||p.contains('فاقد')||p.contains('منتجات ثانوية'))return 'erp_production_variances';if(p.contains('خامات'))return 'erp_production_material_movements';if(p.contains('جودة'))return 'erp_production_quality_checks';return 'erp_production_orders';}
  if(_moduleKey=='contracting'){if(p.contains('مستخلص'))return 'erp_construction_payment_certificates';if(p.contains('تكلفة')||p.contains('مصروفات'))return 'erp_construction_costs';if(p.contains('مقايسة')||p.contains('بنود'))return 'erp_construction_boq_lines';if(p.contains('موقع'))return 'erp_construction_site_reports';return 'erp_construction_projects';}
  if(p.contains('فرص'))return 'erp_crm_leads';if(p.contains('زيارة'))return 'erp_service_visits';if(p.contains('نشاط'))return 'erp_crm_activities';if(p.contains('SLA')||p.contains('استجابة')||p.contains('تذاكر'))return 'erp_service_tickets';return 'erp_service_tickets';
 }
 Map<String,dynamic> _reportRow(Map<String,dynamic> r,String table){
  final id=r['id']?.toString()??'';
  switch(table){
   case 'erp_fixed_assets':return {...r,'record_code':r['asset_code'],'name':r['name'],'amount':r['acquisition_cost']??0,'quantity':1,'record_date':r['acquisition_date'],'counterparty':r['supplier_name']};
   case 'erp_asset_depreciation_runs':return {...r,'record_code':r['run_code'],'name':'تشغيل إهلاك '+(r['period_start']??'').toString(),'amount':r['total_amount']??0,'record_date':r['period_start']};
   case 'erp_asset_movements':return {...r,'record_code':id,'name':r['movement_type'],'amount':0,'record_date':r['movement_date'],'counterparty':r['to_custodian']??r['to_location']};
   case 'erp_asset_disposals':return {...r,'record_code':r['disposal_code'],'name':r['disposal_method'],'amount':r['proceeds']??0,'record_date':r['disposal_date'],'counterparty':r['buyer']};
   case 'erp_production_orders':return {...r,'record_code':r['order_code'],'name':r['product_name'],'amount':r['actual_cost']??r['estimated_cost']??0,'quantity':r['planned_quantity']??0,'record_date':r['planned_start']};
   case 'erp_production_material_movements':return {...r,'record_code':id,'name':r['item_name'],'amount':_n(r['quantity'])*_n(r['unit_cost']),'quantity':r['quantity'],'status':r['movement_type'],'record_date':r['movement_date']};
   case 'erp_production_quality_checks':return {...r,'record_code':id,'name':r['parameter_name'],'amount':0,'quantity':r['inspected_quantity']??0,'status':r['result']};
   case 'erp_production_variances':return {...r,'record_code':r['variance_code'],'name':r['item_name'],'amount':r['amount']??0,'quantity':r['quantity']??0,'record_date':r['movement_date'],'status':r['variance_type']};
   case 'erp_construction_projects':return {...r,'record_code':r['project_code'],'name':r['name'],'amount':r['contract_value']??0,'record_date':r['planned_start']};
   case 'erp_construction_payment_certificates':return {...r,'record_code':r['certificate_number'],'name':'مستخلص مشروع','amount':r['net_amount']??0,'record_date':r['period_start']};
   case 'erp_construction_costs':return {...r,'record_code':id,'name':r['description'],'amount':r['amount']??0,'quantity':r['quantity']??0,'record_date':r['cost_date'],'counterparty':r['supplier_name']};
   case 'erp_construction_boq_lines':return {...r,'record_code':r['item_code']??id,'name':r['description'],'amount':_n(r['planned_quantity'])*_n(r['unit_rate']),'quantity':r['planned_quantity']??0,'status':'active'};
   case 'erp_construction_site_reports':return {...r,'record_code':r['report_code'],'name':r['work_done']??'تقرير موقع','amount':0,'quantity':r['labor_count']??0,'record_date':r['report_date']};
   case 'erp_crm_leads':return {...r,'record_code':r['lead_code'],'name':r['title'],'amount':r['expected_revenue']??0,'record_date':r['expected_close_date'],'counterparty':r['contact_name'],'status':r['stage']};
   case 'erp_service_visits':return {...r,'record_code':r['visit_code'],'name':r['visit_type'],'amount':0,'record_date':r['scheduled_at'],'counterparty':r['assigned_to']};
   case 'erp_crm_activities':return {...r,'record_code':r['activity_code'],'name':r['subject'],'amount':0,'record_date':r['scheduled_at'],'counterparty':r['assigned_to']};
   default:final due=DateTime.tryParse((r['resolution_due_at']??'').toString());final overdue=due!=null&&due.isBefore(DateTime.now())&&!['resolved','closed','cancelled'].contains(r['status']);return {...r,'record_code':r['ticket_code'],'name':r['subject'],'amount':0,'record_date':r['created_at'],'counterparty':r['team_name'],'status':overdue?'متأخر SLA':r['status']};
  }
 }
